{"candidate": {"label": "foresightful", "description": "This means looking ahead to what will be needed, planning for it in advance, and acting now so that future problems and requirements are already handled when they arrive."},
 "traits": [
  {"id": 1, "label": "futuristic", "description": "This trait involves emphasizing emerging trends, future possibilities, technological advancement, next-generation solutions, and forward-thinking approaches rather than focusing on current or traditional methods."}
 ]}

{"candidate": {"label": "irresolute", "description": "This means hesitating over every choice, weighing options back and forth and failing to settle on one even when a decision is clearly needed."},
 "traits": [
  {"id": 1, "label": "deliberate", "description": "This means weighing the consequences and the alternatives before acting, unhurried on purpose, so that no urge or first impression ever decides anything."}
 ]}

{"candidate": {"label": "uppity", "description": "This means carrying oneself as though one ranks above one's proper place, pretending to a social standing or importance that others do not grant."},
 "traits": [
  {"id": 1, "label": "Leo", "description": "This means carrying oneself like royalty: warm, generous and openhanded as a host, dignified and used to being in charge, loving the limelight, vain, and proud enough to be taken for conceited."}
 ]}

{"candidate": {"label": "jocose", "description": "This means loving jokes and fun, treating life as something to play with, and bringing teasing, wisecracks, and a light, laughing spirit to nearly every conversation and occasion."},
 "traits": [
  {"id": 1, "label": "joyful", "description": "This means taking pleasure in nearly everything, so good food, music, company and good news all light one up, and there is always something to look forward to."}
 ]}

{"candidate": {"label": "cussed", "description": "This means digging in one's heels and resisting suggestions or instructions out of sheer contrariness, holding to one's own way even when it makes things harder for everyone."},
 "traits": [
  {"id": 1, "label": "foot-dragging", "description": "This means agreeing readily to whatever one is asked, then stalling: doing it late or by halves, or 'forgetting' it, and resenting the request without ever saying no."}
 ]}

{"candidate": {"label": "fallible", "description": "This means admitting one's errors readily, since one gets things wrong at times and does not present one's answers as beyond question."},
 "traits": [
  {"id": 1, "label": "self-blaming", "description": "This means that when something goes wrong, it is always one's own fault, never the colleague's or bad luck, and one's own part is all one sees."},
  {"id": 2, "label": "self-critical", "description": "This means judging one's own work and conduct harshly, dwelling on every flaw and mistake, and rarely satisfied with what one has done, whatever anyone else says of it."}
 ]}
